  `Hora` time NOT NULL,
  `Monto` double NOT NULL,
  `Estado` tinyint(1) NOT NULL,
  PRIMARY KEY (`NumeroApertura`),
  KEY `fk_AperturasCaja_Cajas1_idx` (`NumeroCaja`),
  KEY `fk_AperturasCaja_Usuarios1_idx` (`CodigoUsuario`),
