  CONSTRAINT `fk_AperturasCaja_Usuarios1` FOREIGN KEY (`CodigoUsuario`) REFERENCES `usuarios` (`CodigoUsuario`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

