/*Table structure for table `condiciones` */

DROP TABLE IF EXISTS `condiciones`;

CREATE TABLE `condiciones` (
  `CodigoCondicion` int(11) NOT NULL,
  `Descripcion` varchar(45) NOT NULL,
  PRIMARY KEY (`CodigoCondicion`),
  UNIQUE KEY `Descripcion_UNIQUE` (`Descripcion`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `condiciones` */

insert  into `condiciones`(`CodigoCondicion`,`Descripcion`) values (1,'CONTADO'),(2,'CREDITO');

/*Table structure for table `cuentascobrar` */

DROP TABLE IF EXISTS `cuentascobrar`;

CREATE TABLE `cuentascobrar` (
  `NumeroCuota` int(11) NOT NULL,
  `NumeroTimbrado` int(11) NOT NULL,
  `CodigoSucursal` varchar(5) NOT NULL,
  `PuntoExpedicion` varchar(5) NOT NULL,
  `NumeroFactura` int(11) NOT NULL,
  `MontoCuota` double NOT NULL,
  `MontoPagado` double NOT NULL,
  `Vencimiento` date NOT NULL,
  `Cancelado` tinyint(1) NOT NULL,
  PRIMARY KEY (`NumeroCuota`,`NumeroTimbrado`,`CodigoSucursal`,`PuntoExpedicion`,`NumeroFactura`),
  KEY `fk_CuentasCobrar_FacturasVentas1_idx` (`NumeroTimbrado`,`CodigoSucursal`,`PuntoExpedicion`,`NumeroFactura`),
  CONSTRAINT `fk_CuentasCobrar_FacturasVentas1` FOREIGN KEY (`NumeroTimbrado`, `CodigoSucursal`, `PuntoExpedicion`, `NumeroFactura`) REFERENCES `facturasventas` (`NumeroTimbrado`, `CodigoSucursal`, `PuntoExpedicion`, `NumeroFactura`) ON DELETE NO ACTION ON UPDATE NO ACTION
