/*Table structure for table `cuentaspagar` */

DROP TABLE IF EXISTS `cuentaspagar`;

CREATE TABLE `cuentaspagar` (
  `NroCuota` int(11) NOT NULL,
  `MontoCuota` float NOT NULL,
  `cancelado` int(11) NOT NULL,
  `Vencimineto` date NOT NULL,
  `NroFactura` varchar(45) NOT NULL,
  PRIMARY KEY (`NroCuota`,`NroFactura`),
  KEY `fk_CuentasPagar_FacturasCompras1_idx` (`NroFactura`),
  CONSTRAINT `fk_CuentasPagar_FacturasCompras1` FOREIGN KEY (`NroFactura`) REFERENCES `facturascompras` (`NroFactura`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

