/*Table structure for table `detallesmovimientoscaja` */

DROP TABLE IF EXISTS `detallesmovimientoscaja`;

CREATE TABLE `detallesmovimientoscaja` (
  `NumeroOperacion` double NOT NULL,
  `NumeroCuota` int(11) NOT NULL,
  `NumeroTimbrado` int(11) NOT NULL,
  `CodigoSucursal` varchar(5) NOT NULL,
  `PuntoExpedicion` varchar(5) NOT NULL,
  `NumeroFactura` int(11) NOT NULL,
  `Monto` double NOT NULL,
  PRIMARY KEY (`NumeroOperacion`,`NumeroCuota`,`NumeroTimbrado`,`CodigoSucursal`,`PuntoExpedicion`,`NumeroFactura`),
  KEY `fk_MovimientosCaja_has_CuentasCobrar_CuentasCobrar1_idx` (`NumeroCuota`,`NumeroTimbrado`,`CodigoSucursal`,`PuntoExpedicion`,`NumeroFactura`),
  KEY `fk_MovimientosCaja_has_CuentasCobrar_MovimientosCaja1_idx` (`NumeroOperacion`),
  CONSTRAINT `fk_MovimientosCaja_has_CuentasCobrar_CuentasCobrar1` FOREIGN KEY (`NumeroCuota`, `NumeroTimbrado`, `CodigoSucursal`, `PuntoExpedicion`, `NumeroFactura`) REFERENCES `cuentascobrar` (`NumeroCuota`, `NumeroTimbrado`, `CodigoSucursal`, `PuntoExpedicion`, `NumeroFactura`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_MovimientosCaja_has_CuentasCobrar_MovimientosCaja1` FOREIGN KEY (`NumeroOperacion`) REFERENCES `movimientoscaja` (`NumeroOperacion`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

