/*Table structure for table `empresas` */

DROP TABLE IF EXISTS `empresas`;

CREATE TABLE `empresas` (
  `CodigoEmpresas` int(11) NOT NULL,
  `RUC` varchar(45) NOT NULL,
  `RazonSocial` varchar(100) NOT NULL,
  `Logo` longblob,
  `Web` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`CodigoEmpresas`),
  UNIQUE KEY `Ruc_UNIQUE` (`RUC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `empresas` */

insert  into `empresas`(`CodigoEmpresas`,`RUC`,`RazonSocial`,`Logo`,`Web`) values (1,'5373184-0','B & R Emprendimientos',NULL,'Web');

/*Table structure for table `entidadesfinancieras` */

DROP TABLE IF EXISTS `entidadesfinancieras`;

CREATE TABLE `entidadesfinancieras` (
  `CodigoEntidadFinanciera` int(11) NOT NULL,
  `RUC` varchar(45) DEFAULT NULL,
  `Nombre` varchar(45) NOT NULL,
  `Direccion` varchar(45) NOT NULL,
  `Telefono` varchar(45) NOT NULL,
  `Email` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`CodigoEntidadFinanciera`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `entidadesfinancieras` */

/*Table structure for table `facturascompras` */

DROP TABLE IF EXISTS `facturascompras`;

CREATE TABLE `facturascompras` (
  `NroFactura` varchar(45) NOT NULL,
  `Fecha` date NOT NULL,
  `Estado` varchar(45) NOT NULL,
  `CodigoCondicion` int(11) NOT NULL,
  `CodigoUsuario` int(11) NOT NULL,
  `CodigoPedido` int(11) NOT NULL,
  `CodigoFormasPago` int(11) NOT NULL,
  `CodigoProveedor` int(11) NOT NULL,
  PRIMARY KEY (`NroFactura`),
  KEY `fk_FacturasCompras_Condicion1_idx` (`CodigoCondicion`),
  KEY `fk_FacturasCompras_Usuarios1_idx` (`CodigoUsuario`),
  KEY `fk_FacturasCompras_PedidoCompras1_idx` (`CodigoPedido`),
  KEY `fk_FacturasCompras_FormasPago1_idx` (`CodigoFormasPago`),
  KEY `fk_FacturasCompras_Proveedores1_idx` (`CodigoProveedor`),
  CONSTRAINT `fk_FacturasCompras_Condicion1` FOREIGN KEY (`CodigoCondicion`) REFERENCES `condiciones` (`CodigoCondicion`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_FacturasCompras_FormasPago1` FOREIGN KEY (`CodigoFormasPago`) REFERENCES `formaspago` (`CodigoFormasPago`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_FacturasCompras_PedidoCompras1` FOREIGN KEY (`CodigoPedido`) REFERENCES `pedidocompras` (`CodigoPedido`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_FacturasCompras_Proveedores1` FOREIGN KEY (`CodigoProveedor`) REFERENCES `proveedores` (`CodigoProveedor`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_FacturasCompras_Usuarios1` FOREIGN KEY (`CodigoUsuario`) REFERENCES `usuarios` (`CodigoUsuario`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `facturascompras` */

/*Table structure for table `facturasventas` */

DROP TABLE IF EXISTS `facturasventas`;

CREATE TABLE `facturasventas` (
  `CodigoTiposDocumento` int(11) NOT NULL,
  `NumeroTimbrado` int(11) NOT NULL,
  `CodigoSucursal` varchar(5) NOT NULL,
  `PuntoExpedicion` varchar(5) NOT NULL,
  `NumeroFactura` int(11) NOT NULL,
  `CodigoCondicion` int(11) NOT NULL,
  `CodigoFormasCobro` int(11) NOT NULL,
  `CodigoCliente` int(11) NOT NULL,
  `Apodo` varchar(100) DEFAULT NULL,
  `CodigoUsuario` int(11) NOT NULL,
  `Fecha` date NOT NULL,
  `Hora` time NOT NULL,
  `Estado` tinyint(4) NOT NULL,
  `TotalLetras` varchar(800) NOT NULL,
  PRIMARY KEY (`NumeroTimbrado`,`CodigoSucursal`,`PuntoExpedicion`,`NumeroFactura`),
  KEY `fk_FacturasVentas_Condiciones1_idx` (`CodigoCondicion`),
  KEY `fk_FacturasVentas_Timbrados1_idx` (`NumeroTimbrado`,`CodigoSucursal`,`PuntoExpedicion`),
  KEY `fk_FacturasVentas_Usuarios1_idx` (`CodigoUsuario`),
  KEY `fk_FacturasVentas_Clientes1_idx` (`CodigoCliente`),
  KEY `fk_FacturasVentas_FormasCobros2_idx` (`CodigoFormasCobro`),
  KEY `fk_FacturasVentas_TiposDocumento1_idx` (`CodigoTiposDocumento`),
  CONSTRAINT `fk_FacturasVentas_Clientes1` FOREIGN KEY (`CodigoCliente`) REFERENCES `clientes` (`CodigoCliente`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_FacturasVentas_Condiciones1` FOREIGN KEY (`CodigoCondicion`) REFERENCES `condiciones` (`CodigoCondicion`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_FacturasVentas_FormasCobros2` FOREIGN KEY (`CodigoFormasCobro`) REFERENCES `formascobro` (`CodigoFormasCobro`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_FacturasVentas_Timbrados1` FOREIGN KEY (`NumeroTimbrado`, `CodigoSucursal`, `PuntoExpedicion`) REFERENCES `timbrados` (`NumeroTimbrado`, `CodigoSucursal`, `PuntoExpedicion`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_FacturasVentas_TiposDocumento1` FOREIGN KEY (`CodigoTiposDocumento`) REFERENCES `tiposdocumento` (`Codigo`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_FacturasVentas_Usuarios1` FOREIGN KEY (`CodigoUsuario`) REFERENCES `usuarios` (`CodigoUsuario`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

