/*Table structure for table `formascobro` */

DROP TABLE IF EXISTS `formascobro`;

CREATE TABLE `formascobro` (
  `CodigoFormasCobro` int(11) NOT NULL,
  `Descripcion` varchar(45) DEFAULT NULL,
  `plazo` tinyint(4) DEFAULT NULL,
  `dias` tinyint(4) DEFAULT NULL,
  `estado` tinyint(4) DEFAULT NULL,
  PRIMARY KEY (`CodigoFormasCobro`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `formascobro` */

insert  into `formascobro`(`CodigoFormasCobro`,`Descripcion`,`plazo`,`dias`,`estado`) values (0,'COBRO CONTADO',1,0,1),(1,'COBRO CREDITO',1,0,1);

/*Table structure for table `formaspago` */

DROP TABLE IF EXISTS `formaspago`;

CREATE TABLE `formaspago` (
  `CodigoFormasPago` int(11) NOT NULL,
  `Descripcion` varchar(45) NOT NULL,
  `Plazo` tinyint(4) NOT NULL,
  `Dias` tinyint(4) NOT NULL,
  `Estado` tinyint(4) NOT NULL,
  PRIMARY KEY (`CodigoFormasPago`),
  UNIQUE KEY `Descripcion_UNIQUE` (`Descripcion`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `formaspago` */

/*Table structure for table `listaprecios` */

DROP TABLE IF EXISTS `listaprecios`;

CREATE TABLE `listaprecios` (
  `Codigo` double NOT NULL,
  `codigoDeposito` int(11) NOT NULL,
  `CodigoProducto` int(11) NOT NULL,
  `Descripcion` varchar(100) NOT NULL,
  `Precio` int(20) NOT NULL,
  `Porcentaje` float NOT NULL,
  `PrecioCompra` double NOT NULL,
  `Cuotas` int(11) NOT NULL,
  PRIMARY KEY (`Codigo`),
  KEY `fk_ListaPrecios_Stock1_idx` (`codigoDeposito`,`CodigoProducto`),
  CONSTRAINT `fk_ListaPrecios_Stock1` FOREIGN KEY (`codigoDeposito`, `CodigoProducto`) REFERENCES `stock` (`codigoDeposito`, `CodigoProducto`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

