/*Table structure for table `movimientoscaja` */

DROP TABLE IF EXISTS `movimientoscaja`;

CREATE TABLE `movimientoscaja` (
  `NumeroOperacion` double NOT NULL,
  `NumeroApertura` double NOT NULL,
  `CodigoOperacion` int(11) NOT NULL,
  `Fecha` date NOT NULL,
  `Hora` time NOT NULL,
  `Descripcion` varchar(250) NOT NULL,
  `Estado` tinyint(4) NOT NULL,
  PRIMARY KEY (`NumeroOperacion`),
  KEY `fk_MovimientosCaja_AperturasCaja1_idx` (`NumeroApertura`),
  KEY `fk_MovimientosCaja_Operaciones1_idx` (`CodigoOperacion`),
  CONSTRAINT `fk_MovimientosCaja_AperturasCaja1` FOREIGN KEY (`NumeroApertura`) REFERENCES `aperturascaja` (`NumeroApertura`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_MovimientosCaja_Operaciones1` FOREIGN KEY (`CodigoOperacion`) REFERENCES `operaciones` (`CodigoOperacion`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

