/*Table structure for table `nivelesusuarios` */

DROP TABLE IF EXISTS `nivelesusuarios`;

CREATE TABLE `nivelesusuarios` (
  `CodigoNivel` int(11) NOT NULL,
  `Descripcion` varchar(45) NOT NULL,
  PRIMARY KEY (`CodigoNivel`),
  UNIQUE KEY `descripcion_UNIQUE` (`Descripcion`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `nivelesusuarios` */

insert  into `nivelesusuarios`(`CodigoNivel`,`Descripcion`) values (1,'ADMINISTRADOR'),(3,'ASESOR DE VENTAS'),(2,'CAJERO');

/*Table structure for table `operaciones` */

DROP TABLE IF EXISTS `operaciones`;

CREATE TABLE `operaciones` (
  `CodigoOperacion` int(11) NOT NULL,
  `Descripcion` varchar(90) NOT NULL,
  `CodigoTiposMovimiento` int(11) NOT NULL,
  PRIMARY KEY (`CodigoOperacion`),
  UNIQUE KEY `Descripcion_UNIQUE` (`Descripcion`),
  KEY `fk_Operaciones_TiposMovimiento1_idx` (`CodigoTiposMovimiento`),
  CONSTRAINT `fk_Operaciones_TiposMovimiento1` FOREIGN KEY (`CodigoTiposMovimiento`) REFERENCES `tiposmovimiento` (`CodigoTiposMovimiento`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `operaciones` */

insert  into `operaciones`(`CodigoOperacion`,`Descripcion`,`CodigoTiposMovimiento`) values (1,'VENTAS CONTADO',1),(2,'EGRESO CAJA CHICA',2),(3,'COBRO DE CUOTAS',1);

/*Table structure for table `paises` */

DROP TABLE IF EXISTS `paises`;

CREATE TABLE `paises` (
  `CodigoPais` int(11) NOT NULL,
  `Nombre` varchar(45) NOT NULL,
  PRIMARY KEY (`CodigoPais`),
  UNIQUE KEY `Nombre_UNIQUE` (`Nombre`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `paises` */

insert  into `paises`(`CodigoPais`,`Nombre`) values (1,'PARAGUAY');

/*Table structure for table `pedidocompras` */

DROP TABLE IF EXISTS `pedidocompras`;

CREATE TABLE `pedidocompras` (
  `CodigoPedido` int(11) NOT NULL,
  `Fecha` date NOT NULL,
  `Estado` int(11) NOT NULL,
  `CodigoProveedor` int(11) NOT NULL,
  `CodigoUsuario` int(11) NOT NULL,
  PRIMARY KEY (`CodigoPedido`),
  KEY `fk_PedidoCompras_Proveedores1_idx` (`CodigoProveedor`),
  KEY `fk_PedidoCompras_Usuarios1_idx` (`CodigoUsuario`),
  CONSTRAINT `fk_PedidoCompras_Proveedores1` FOREIGN KEY (`CodigoProveedor`) REFERENCES `proveedores` (`CodigoProveedor`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_PedidoCompras_Usuarios1` FOREIGN KEY (`CodigoUsuario`) REFERENCES `usuarios` (`CodigoUsuario`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `pedidocompras` */

/*Table structure for table `productos` */

DROP TABLE IF EXISTS `productos`;

CREATE TABLE `productos` (
  `CodigoProducto` int(11) NOT NULL,
  `CodigoBarra` varchar(45) NOT NULL,
  `Descripcion` varchar(100) NOT NULL,
  `CantidadPaquete` double NOT NULL DEFAULT '1',
  `Peso` double NOT NULL DEFAULT '0',
  `Perecedero` varchar(2) NOT NULL DEFAULT '0',
  `Estado` int(11) NOT NULL DEFAULT '1',
  `CodigoRepresentante` int(11) NOT NULL,
  `CodigoUnidad` int(11) NOT NULL,
  `CodigoMarca` int(11) NOT NULL,
  `CodigoCategoria` int(11) NOT NULL,
  `CodigImpuesto` int(11) NOT NULL,
  PRIMARY KEY (`CodigoProducto`),
  UNIQUE KEY `CodigoBarra_UNIQUE` (`CodigoBarra`),
  KEY `fk_Mercaderias_Representante1_idx` (`CodigoRepresentante`),
  KEY `fk_Mercaderias_UnidadMedida1_idx` (`CodigoUnidad`),
  KEY `fk_Mercaderias_Marcas1_idx` (`CodigoMarca`),
  KEY `fk_Mercaderias_Categorias1_idx` (`CodigoCategoria`),
  KEY `fk_Mercaderias_TipoImpuesto1_idx` (`CodigImpuesto`),
  CONSTRAINT `fk_Mercaderias_Categorias1` FOREIGN KEY (`CodigoCategoria`) REFERENCES `categorias` (`CodigoCategoria`) ON UPDATE CASCADE,
  CONSTRAINT `fk_Mercaderias_Marcas1` FOREIGN KEY (`CodigoMarca`) REFERENCES `marcas` (`CodigoMarca`) ON UPDATE CASCADE,
  CONSTRAINT `fk_Mercaderias_Representante1` FOREIGN KEY (`CodigoRepresentante`) REFERENCES `representante` (`CodigoRepresentante`) ON UPDATE CASCADE,
  CONSTRAINT `fk_Mercaderias_TipoImpuesto1` FOREIGN KEY (`CodigImpuesto`) REFERENCES `tipoimpuesto` (`CodigImpuesto`) ON UPDATE CASCADE,
  CONSTRAINT `fk_Mercaderias_UnidadMedida1` FOREIGN KEY (`CodigoUnidad`) REFERENCES `unidadmedida` (`CodigoUnidad`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

