/*Table structure for table `proveedores` */

DROP TABLE IF EXISTS `proveedores`;

CREATE TABLE `proveedores` (
  `CodigoProveedor` int(11) NOT NULL,
  `RazonSocial` varchar(100) NOT NULL,
  `Cedula` varchar(45) NOT NULL,
  `Ruc` varchar(45) NOT NULL,
  `Direccion` varchar(45) NOT NULL,
  `Telefono` varchar(45) NOT NULL,
  `Email` varchar(45) DEFAULT NULL,
  `Web` varchar(45) DEFAULT NULL,
  `CodigoCiudad` int(11) NOT NULL,
  PRIMARY KEY (`CodigoProveedor`),
  UNIQUE KEY `Email_UNIQUE` (`Email`),
  KEY `fk_Proveedores_Ciudades1_idx` (`CodigoCiudad`),
  CONSTRAINT `fk_Proveedores_Ciudades1` FOREIGN KEY (`CodigoCiudad`) REFERENCES `ciudades` (`CodigoCiudad`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `proveedores` */

/*Table structure for table `representante` */

DROP TABLE IF EXISTS `representante`;

CREATE TABLE `representante` (
  `CodigoRepresentante` int(11) NOT NULL,
  `Descripcion` varchar(45) NOT NULL,
  PRIMARY KEY (`CodigoRepresentante`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `representante` */

insert  into `representante`(`CodigoRepresentante`,`Descripcion`) values (1,'NO DEFINIDO');

/*Table structure for table `stock` */

DROP TABLE IF EXISTS `stock`;

CREATE TABLE `stock` (
  `codigoDeposito` int(11) NOT NULL,
  `CodigoProducto` int(11) NOT NULL,
  `StockActual` double NOT NULL,
  `StockMinimo` double NOT NULL,
  `StockMaximo` double NOT NULL,
  `PrecioCompra` double NOT NULL,
  `UtilidadMinima` double NOT NULL,
  `UtilidadMaxima` double NOT NULL,
  `PrecioVentaMinorista` double NOT NULL,
  `PrecioVentaMayorista` double NOT NULL,
  `Estante` int(11) NOT NULL DEFAULT '0',
  `Fila` int(11) NOT NULL DEFAULT '0',
  `Columna` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`codigoDeposito`,`CodigoProducto`),
  KEY `fk_Mercaderias_has_Depositos_Depositos1_idx` (`codigoDeposito`),
  KEY `fk_Stock_Productos1_idx` (`CodigoProducto`),
  CONSTRAINT `fk_Mercaderias_has_Depositos_Depositos1` FOREIGN KEY (`codigoDeposito`) REFERENCES `depositos` (`codigoDeposito`) ON UPDATE CASCADE,
  CONSTRAINT `fk_Stock_Productos1` FOREIGN KEY (`CodigoProducto`) REFERENCES `productos` (`CodigoProducto`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

