/*Table structure for table `sucursales` */

DROP TABLE IF EXISTS `sucursales`;

CREATE TABLE `sucursales` (
  `CodigoSucursal` varchar(5) NOT NULL,
  `CodigoEmpresas` int(11) NOT NULL,
  `CodigoCiudad` int(11) NOT NULL,
  `Nombre` varchar(100) NOT NULL,
  `Direccion` varchar(100) NOT NULL,
  `Telefono` varchar(45) DEFAULT NULL,
  `Celular` varchar(45) NOT NULL,
  `Email` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`CodigoSucursal`),
  KEY `fk_Sucursales_Empresas_idx` (`CodigoEmpresas`),
  KEY `fk_Sucursales_Ciudades1_idx` (`CodigoCiudad`),
  CONSTRAINT `fk_Sucursales_Ciudades1` FOREIGN KEY (`CodigoCiudad`) REFERENCES `ciudades` (`CodigoCiudad`) ON UPDATE CASCADE,
  CONSTRAINT `fk_Sucursales_Empresas` FOREIGN KEY (`CodigoEmpresas`) REFERENCES `empresas` (`CodigoEmpresas`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `sucursales` */

insert  into `sucursales`(`CodigoSucursal`,`CodigoEmpresas`,`CodigoCiudad`,`Nombre`,`Direccion`,`Telefono`,`Celular`,`Email`) values ('001',1,1,'SUCURSAL 1','Direccion','Telefono','Celular','Email');

/*Table structure for table `timbrados` */

DROP TABLE IF EXISTS `timbrados`;

CREATE TABLE `timbrados` (
  `NumeroTimbrado` int(11) NOT NULL,
  `CodigoSucursal` varchar(5) NOT NULL,
  `PuntoExpedicion` varchar(5) NOT NULL,
  `CodigoTiposDocumento` int(11) NOT NULL,
  `FechaInicioVigencia` date NOT NULL,
  `FechaFinVigencia` date NOT NULL,
  `NumeroInicial` int(11) NOT NULL,
  `NumeroFinal` int(11) NOT NULL,
  `Estado` tinyint(4) NOT NULL,
  PRIMARY KEY (`NumeroTimbrado`,`CodigoSucursal`,`PuntoExpedicion`),
  KEY `fk_Timbrados_TiposDocumento1_idx` (`CodigoTiposDocumento`),
  KEY `fk_Timbrados_Sucursales1_idx` (`CodigoSucursal`),
  CONSTRAINT `fk_Timbrados_Sucursales1` FOREIGN KEY (`CodigoSucursal`) REFERENCES `sucursales` (`CodigoSucursal`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_Timbrados_TiposDocumento1` FOREIGN KEY (`CodigoTiposDocumento`) REFERENCES `tiposdocumento` (`Codigo`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

